    Bug 1983370 - Fix up/down keys in global search bar. r=freaktechnik


    Since bug 1969859, the 'keydown' listener has already been added by the parent element.

    See https://bugzilla.mozilla.org/show_bug.cgi?id=1983370#c3

    Differential Revision: https://phabricator.services.mozilla.com/D262909

diff --git a/mail/components/unifiedtoolbar/content/items/global-search-bar.mjs b/mail/components/unifiedtoolbar/content/items/global-search-bar.mjs
index 3563f838a8a..fde91b9a8f7 100644
--- a/mail/components/unifiedtoolbar/content/items/global-search-bar.mjs
+++ b/mail/components/unifiedtoolbar/content/items/global-search-bar.mjs
@@ -87,10 +87,6 @@ class GlobalSearchBar extends SearchBar {
     super.connectedCallback();
     this.addEventListener("search", this);
     this.addEventListener("autocomplete", this);
-    // Capturing to avoid the default cursor movements inside the input.
-    this.addEventListener("keydown", this, {
-      capture: true,
-    });
     this.addEventListener("focus", this);
     this.addEventListener("blur", this);
     this.addEventListener("drop", this, { capture: true });
